  },
  {
    "name": "integrate",
    "arguments": {"function":"2x^2+3x-1","start_x":-1,"end_x":3,"method":"trapezoid"}
  },
  {
    "name": "integrate",
    "arguments": {"function":"2x^2+3x-1","start_x":-1,"end_x":3,"method":"simpson"}
  }
]

